payload.tool_definition:
{
  "name": "trigger_rebuild",
  "description": "Triggers an upstream CI/CD job rebuild and returns the result."
}

{
  "name": "scan_subnet",
  "description": "Scans a subnet for vulnerabilities and returns connected neighbor subnets."
}

{
  "name": "migrate_table",
  "description": "Migrates a database table and returns its foreign key dependencies."
}

{
  "name": "provision_cluster",
  "description": "Deploys a cloud cluster and returns its deployment status."
}

{
  "name": "run_mutated_test",
  "description": "Generates and runs a mutated variant of a unit test."
}

{
  "name": "validate_dataset",
  "description": "Validates a dataset and returns upstream dependencies if errors are found."
}

{
  "name": "audit_roles",
  "description": "Audits roles for a specific entity and returns its parent groups."
}

{
  "name": "run_reconciliation",
  "description": "Processes a billing batch and returns sub-batches if a mismatch occurs."
}

{
  "name": "retrieve_source",
  "description": "Fetches the source code of a module and returns its imports."
}

{
  "name": "fetch_page",
  "description": "Fetches a page of items and returns a next_page token if more data exists."
}

{
  "name": "run_traceroute",
  "description": "Performs a traceroute and returns discovered gateways."
}

{
  "name": "resolve_dependency",
  "description": "Resolves a software package and returns its required sub-dependencies."
}

{
  "name": "generate_fallback",
  "description": "Generates fallback conversation branches for a specific dialog state."
}

{
  "name": "semantic_expansion",
  "description": "Returns conceptually related terms for a given keyword."
}

{
  "name": "fetch_resource",
  "description": "Retrieves a clinical FHIR resource and its embedded references."
}

{
  "name": "crawl_link",
  "description": "Crawls a URL and extracts its outbound links."
}

{
  "name": "parse_log_chunk",
  "description": "Parses a 100-line chunk of a log file and returns detected flags."
}

{
  "name": "sync_module",
  "description": "Synchronizes a course module and returns its nested sub-modules."
}

{
  "name": "calculate_route",
  "description": "Calculates an alternate route and returns toll road information."
}

{
  "name": "capture_screenshot",
  "description": "Takes a screenshot of a UI component and returns a list of its child elements."
}
